{
  "case_id": "C10",
  "audience": "General public with secondary-school science literacy",
  "target_duration_s": 60,
  "beats": [
    {
      "beat": "The trial",
      "narration": "An experimental drug called CardioRestore-7 was tested in 1,204 adults with heart failure, the kind where the heart pumps too weakly. Half received the drug, half a dummy treatment, for 52 weeks, and nobody knew who got what.",
      "on_screen": "Title: CardioRestore-7 vs placebo. 1,204 adults, 602 per group, 52 weeks, double-blind, randomised 1:1.",
      "claim_refs": ["Abstract: 1,204 adults with stable HFrEF, placebo-controlled", "Methods: double-blind, 52 weeks, randomisation 1:1 with allocation concealment"]
    },
    {
      "beat": "The main result was null",
      "narration": "The question set in advance was whether it would reduce deaths from heart disease or hospital stays for heart failure. It did not. There were 187 such events on the drug and 193 on placebo, a gap easily explained by chance.",
      "on_screen": "PRIMARY ENDPOINT: 187/602 drug vs 193/602 placebo. Hazard ratio 0.96 (95% CI 0.79-1.17), p = 0.68. Verdict: no difference.",
      "claim_refs": ["Abstract/Results: primary composite at 52 weeks, HR 0.96 (0.79-1.17), p = 0.68 - null"]
    },
    {
      "beat": "The walking distance signal",
      "narration": "One lesser measure did shift: people on the drug walked 14 metres further in a six-minute test. But researchers generally treat about 30 metres as the smallest difference a patient would actually notice, and this secondary result was not statistically corrected for testing several outcomes at once.",
      "on_screen": "Six-minute walk: +14 m (95% CI 3 to 25). Usual threshold for a difference that matters: above 30 m. Secondary endpoint, not adjusted for multiplicity.",
      "claim_refs": ["Results: six-minute walk distance +14 m (95% CI 3 to 25)", "Background: minimum clinically important difference generally placed above 30 metres", "Methods: pre-specified secondary endpoint, not adjusted for multiplicity"]
    },
    {
      "beat": "The side effect",
      "narration": "There was also a downside. Blood pressure dropped low enough to require cutting the dose in 47 people on the drug, compared with 12 on placebo, roughly four times as many.",
      "on_screen": "Hypotension requiring dose reduction: 47/602 on drug vs 12/602 on placebo.",
      "claim_refs": ["Abstract/Results: hypotension requiring dose reduction, 47/602 vs 12/602", "Methods: hypotension defined as systolic BP below 90 mmHg with symptoms or requiring dose reduction"]
    },
    {
      "beat": "Bottom line",
      "narration": "So: one 52-week trial, no benefit on the outcome that mattered most, a small walking gain below the usual bar, and more low blood pressure. CardioRestore-7 is still investigational and is not approved by any regulator.",
      "on_screen": "Single trial, 52 weeks. Primary endpoint: null. CardioRestore-7 is investigational and not approved by any regulator.",
      "claim_refs": ["Limitations: single trial; 52 weeks of follow-up", "Results/Abstract: regulatory status - investigational, not approved"]
    }
  ]
}
